mapper.select:
		/** [sql-fault.xml] FaultMapper.getSeq **/
		SELECT COALESCE(MAX(ST08_SEQ)+1,1) AS ST08_SEQ
          FROM TB_ST_08
          WHERE ST08_COMPANY = #{st08Company}
            AND ST08_FACTORY = #{st08Factory}
            AND TO_CHAR(ST08_DAT, 'YYYYMMDD') = TO_CHAR(TO_DATE(#{st08Dat}, 'YYMMDDHH24MI'), 'YYYYMMDD')

/** [sql-fault.xml] FaultMapper.getFaultInfo **/
SELECT * 
FROM TB_ST_08
WHERE 1=1
AND ST08_COMPANY 	= #{st08Company}
AND ST08_FACTORY 	= #{st08Factory}
AND ST08_QRCODE 	= #{st08Qrcode}

mapper.insert:
    	/** [sql-fault.xml] FaultMapper.insertOfFault **/
        INSERT INTO TB_ST_08
		(
			  ST08_COMPANY
			, ST08_FACTORY
			, ST08_NO
			, ST08_DAT
			, ST08_SEQ
			, ST08_GBN
			, ST08_PGBN
			, ST08_CODE
			, ST08_UNT
			, ST08_LOT
			, ST08_RMK
			, ST08_INDTE
			, ST08_EMPNO
			, ST08_QTY
			, ST08_LOT_SEQ
			, ST08_QRCODE
			, ST08_LINE
			, ST08_EQUIP_CODE
		)
		VALUES
		(
			  #{st08Company}
			, #{st08Factory}
			, CONCAT(TO_CHAR(SYSDATE, 'YYYYMMDD'), LPAD(#{st08Seq}, 5, '0'))
			, SYSDATE
			, #{st08Seq}
			, #{st08Gbn}
			, #{st08Pgbn}
			, #{st08Code}
			, #{st08Unt}
			, #{st08Lot}
			, '[PDA]PCB 공정 불량처리'
			, SYSDATE
			, #{st08Empno}
			, 1
			, #{st08LotSeq}
			, #{st08Qrcode}
			, #{st08Line}
			, #{st08EquipCode}
		)
